// Some portions generated by Codex
package org.eclipse.rdf4j.rio.trix;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;

import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.rio.helpers.XMLWriterSettings;
import org.junit.jupiter.api.Test;

class TriXWriterCapabilityTest {

	private static final Statement STATEMENT = SimpleValueFactory.getInstance()
			.createStatement(
					SimpleValueFactory.getInstance().createIRI("urn:trix:subject"),
					SimpleValueFactory.getInstance().createIRI("urn:trix:predicate"),
					SimpleValueFactory.getInstance().createLiteral("object"));

	@Test
	void advertisesXmlDeclarationSettingAndRoundTripsBothDeclarationModes() throws Exception {
		TriXWriter writer = new TriXWriter(new ByteArrayOutputStream());
		assertThat(writer.getSupportedSettings()).contains(XMLWriterSettings.INCLUDE_XML_PI);

		for (boolean includeXmlDeclaration : new boolean[] { true, false }) {
			ByteArrayOutputStream output = new ByteArrayOutputStream();
			writer = new TriXWriter(output);
			writer.set(XMLWriterSettings.INCLUDE_XML_PI, includeXmlDeclaration);
			writer.startRDF();
			writer.handleStatement(STATEMENT);
			writer.endRDF();

			String serialized = output.toString(StandardCharsets.UTF_8);
			assertThat(serialized.contains("<?xml")).isEqualTo(includeXmlDeclaration);
			Model parsed = Rio.parse(new ByteArrayInputStream(output.toByteArray()), "urn:trix:base:", RDFFormat.TRIX);
			assertThat(parsed).hasSize(1);
		}
	}
}
